    "type": "mecquoise",
    "versets_count": 206,
    "theme": "La grande fresque de la mémoire prophétique : Adam et Iblīs, puis Noé, Hūd, Ṣāliḥ, Loth, Shuʿayb et surtout Moïse face à Pharaon — et, entre Paradis et Enfer, les gens des Aʿrāf, sur les hauteurs qui séparent",
    "note_pedagogique": "Nommée d'après les Aʿrāf, les hauteurs entre le Paradis et l'Enfer d'où des hommes observent les deux demeures (v.46-49). Longue sourate mecquoise qui déroule l'histoire des prophètes comme un avertissement, culmine avec l'épopée de Moïse, le pacte primordial des âmes (« Ne suis-Je pas votre Seigneur ? »), et s'achève sur l'ordre du pardon et de la mesure.",
